import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

// The site and repository guide share one source; do not hand-edit the export.
const root = new URL("../", import.meta.url);
const guide = JSON.parse(
  readFileSync(
    new URL("web/src/modules/system/help-content.json", root),
    "utf8",
  ),
);
const output = new URL("docs/user-guide.zh-CN.md", root);
const lines = [
  "<!-- Generated by node scripts/export-user-guide.mjs. Edit web/src/modules/system/help-content.json. -->",
  "# GloryNavy SeAT 使用指南",
  "",
  `更新：${guide.updated} · [站内使用帮助](https://seat.kisectool.com/help)`,
  "",
  guide.intro,
  "",
  "## 目录",
  "",
];
for (const group of guide.groups) {
  lines.push(`**${group}**`, "");
  for (const article of guide.articles.filter((item) => item.group === group))
    lines.push(`- [${article.title}](#${article.id})`);
  lines.push("");
}
for (const group of guide.groups)
  for (const article of guide.articles.filter((item) => item.group === group)) {
    lines.push(
      `<a id="${article.id}"></a>`,
      "",
      `## ${article.title}`,
      "",
      article.summary,
      "",
    );
    if (article.links.length)
      lines.push(
        article.links
          .map(
            (link) => `[${link.label}](https://seat.kisectool.com${link.path})`,
          )
          .join(" · "),
        "",
      );
    for (const section of article.sections) {
      lines.push(`### ${section.title}`, "");
      section.steps.forEach((step, index) =>
        lines.push(`${index + 1}. ${step}`),
      );
      if (section.steps.length) lines.push("");
      section.notes.forEach((note) => lines.push(`- ${note}`));
      if (section.notes.length) lines.push("");
    }
    for (const question of article.questions)
      lines.push(`### ${question.title}`, "", question.answer, "");
  }
const content = lines.join("\n");
if (process.argv.includes("--check")) {
  if (readFileSync(output, "utf8").replace(/\r\n/g, "\n") !== content)
    throw new Error(
      "Run node scripts/export-user-guide.mjs to update the repository guide.",
    );
  console.log("User guide export is current.");
} else {
  writeFileSync(output, content);
  console.log(`Wrote ${fileURLToPath(output)}`);
}
